def transform(grid):
    n = len(grid)
    if not n:
        return []
    m = len(grid[0])
    pts = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    colors = sorted({v for _, _, v in pts})
    k = len(colors)

    # Diagonal stripe patterns: the color is fixed by a diagonal invariant,
    # modulo the number of colors. Select the orientation supported by input.
    if len(pts) > 1 and k > 1:
        for invariant in (lambda r, c: c-r, lambda r, c: r+c):
            residues = {}
            valid = True
            for r, c, v in pts:
                q = invariant(r, c) % k
                if q in residues and residues[q] != v:
                    valid = False
                    break
                residues[q] = v
            if valid and len(residues) == k:
                return [[residues[invariant(r, c) % k] for c in range(m)] for r in range(n)]

    # Horizontal stripe patterns: find the shortest row period consistent
    # with all observed nonempty rows, then fill missing rows.
    known = {}
    for r, row in enumerate(grid):
        vals = {v for v in row if v != 0}
        if len(vals) == 1:
            known[r] = next(iter(vals))
    for p in range(1, n + 1):
        motif = [None] * p
        for r, v in known.items():
            q = r % p
            if motif[q] is not None and motif[q] != v:
                break
            motif[q] = v
        else:
            if all(v is not None for v in motif):
                return [[motif[r % p]] * m if all(x == 0 for x in grid[r]) else grid[r][:] for r in range(n)]
    return [row[:] for row in grid]
